{
  "service": "gateway",
  "description": "gateway edge proxy",
  "listen": {
    "address": "127.0.0.1",
    "port": 8080
  },
  "tls": {
    "enabled": true,
    "verify_upstream": true,
    "min_version": "1.2"
  },
  "logging": {
    "level": "info",
    "format": "json",
    "sample_rate_pct": 100
  },
  "limits": {
    "max_body_kib": 512,
    "max_connections": 2048,
    "idle_timeout_s": 60
  },
  "features": {
    "compression": true,
    "http2": true,
    "request_ids": true
  },
  "upstreams": [
    {
      "name": "accounts",
      "host": "accounts.internal",
      "port": 7469,
      "weight": 7,
      "health_check": "/healthz"
    },
    {
      "name": "search",
      "host": "search.internal",
      "port": 8565,
      "weight": 3,
      "health_check": "/healthz"
    },
    {
      "name": "orders",
      "host": "orders.internal",
      "port": 9965,
      "weight": 8,
      "health_check": "/healthz"
    },
    {
      "name": "reviews",
      "host": "reviews.internal",
      "port": 8361,
      "weight": 2,
      "health_check": "/healthz"
    },
    {
      "name": "shipping",
      "host": "shipping.internal",
      "port": 8264,
      "weight": 8,
      "health_check": "/healthz"
    }
  ],
  "routes": [
    {
      "path": "/api/v1/reviews/lookup",
      "upstream": "reviews",
      "methods": [
        "GET"
      ],
      "timeout_ms": 2500,
      "retries": 2
    },
    {
      "path": "/api/v1/accounts/history",
      "upstream": "accounts",
      "methods": [
        "POST"
      ],
      "timeout_ms": 1000,
      "retries": 3
    },
    {
      "path": "/api/v1/orders/status",
      "upstream": "orders",
      "methods": [
        "GET",
        "POST"
      ],
      "timeout_ms": 2500,
      "retries": 0
    },
    {
      "path": "/api/v1/shipping/history",
      "upstream": "shipping",
      "methods": [
        "POST"
      ],
      "timeout_ms": 2000,
      "retries": 2
    },
    {
      "path": "/api/v1/orders/events",
      "upstream": "orders",
      "methods": [
        "POST"
      ],
      "timeout_ms": 5000,
      "retries": 0
    },
    {
      "path": "/api/v1/reviews/history",
      "upstream": "reviews",
      "methods": [
        "GET",
        "PUT"
      ],
      "timeout_ms": 1000,
      "retries": 2
    },
    {
      "path": "/api/v1/accounts/labels",
      "upstream": "accounts",
      "methods": [
        "GET",
        "POST",
        "PATCH"
      ],
      "timeout_ms": 1000,
      "retries": 1
    },
    {
      "path": "/api/v1/search/status",
      "upstream": "search",
      "methods": [
        "GET",
        "POST",
        "PATCH"
      ],
      "timeout_ms": 2500,
      "retries": 3
    },
    {
      "path": "/api/v1/accounts/items",
      "upstream": "accounts",
      "methods": [
        "GET",
        "POST"
      ],
      "timeout_ms": 2500,
      "retries": 1
    }
  ]
}

